import {escapeHTML as esc} from './core.js';
import {CONFESSION_THEMES,CONFESSION_RESPONSES} from './confession-copy.js';
export function createConfession({t,prefs,render,focusMain}) {
 const s={view:'room',busy:false,error:'',moderator:false,body:'',theme:'loneliness',responseType:'listen',consent:false,audio:null,audioURL:null,textInstead:false,items:[],reports:[],reserved:[],detail:null,reply:null,replyDraft:'',note:'',report:null,recording:false,success:'',support:false};
 let recorder,stream,timer;
 const tx=k=>esc(t(k));
 const btn=(label,action,cls='',extra='')=>`<button class="c-button ${cls}" data-confession="${action}" ${s.busy?'disabled':''} ${extra}>${tx(label)}</button>`;
 const api=async(action,data={})=>{let r;if(['status','list','mine','read','queue'].includes(action))r=await fetch('/api/confessions?'+new URLSearchParams({action,...data}),{cache:'no-store'});else{let body,headers;if(action==='share'&&s.audio){body=new FormData();body.append('data',JSON.stringify({action,...data}));body.append('audio',s.audio,'recording');}else{body=JSON.stringify({action,...data});headers={'Content-Type':'application/json'};}r=await fetch('/api/confessions',{method:'POST',body,headers});}let result;try{result=await r.json();}catch{throw Error('unavailable');}if(!r.ok)throw Error(result.error);return result;};
 function error(e){s.error=t(['not_available','not_found'].includes(e.message)?'cUnavailable':e.message==='sign_in_required'?'cSignIn':e.message==='invalid_audio'?'cAudioLimit':'cError');}
 async function run(fn){if(s.busy)return;s.busy=true;s.error='';render();try{await fn();}catch(e){error(e);}finally{s.busy=false;render();focusMain();}}
 const lattice='<svg class="c-lattice" viewBox="0 0 64 64" aria-hidden="true"><rect x="5" y="5" width="54" height="54" rx="18"/><path d="m14 17 33 33M22 9l33 33M9 29l26 26M17 50l33-33M9 42 33 18m-4 37 26-26"/></svg>';
 const status=x=>`<p class="c-status">${tx(x.status==='pending'?(x.kind==='reply'?'cReplyPending':'cPending'):x.status==='reported'?'cReported':x.status==='rejected'?'cRejected':x.closed?'cClosed':'cApproved')}</p>`;
 const audio=x=>x.hasAudio?`<label class="c-label">${tx('cAudio')}</label><audio controls preload="none" src="/api/confessions?action=audio&amp;id=${esc(x.id)}"></audio>`:'';
 const meta=x=>`<div class="c-tags"><span>${tx('c_'+x.theme)}</span><span>${tx('c_'+x.responseType)}</span></div>`;
 const audience=()=>`<details class="c-audience" open><summary>${tx('cAudienceTitle')}</summary><p>${tx('cAudience')}</p><p>${tx('cOneReply')}</p></details>`;
 const item=x=>`<article class="c-paper">${meta(x)}${s.view==='review'?`<p class="c-status">${esc(x.signals.join(' · ')||'Routine review')}${s.reports.filter(r=>r.target===x.id).map(r=>' · '+tx('c_'+r.reason)).join('')} · ${esc(String(x.priority))}</p>`:''}${x.body?`<p class="c-confession-text">${esc(x.body)}</p>`:''}${audio(x)}${status(x)}</article>`;
 const listRow=x=>`<button class="c-list-row" data-confession="open" data-id="${esc(x.id)}" ${s.busy?'disabled':''}>${meta(x)}<span>${tx(x.hasAudio?'cAudio':'cBody')} <span aria-hidden="true">↗</span></span></button>`;
 function view(){
 let html='';
 if(s.view==='room')html=`<div class="c-entrance">${lattice}<p class="c-eyebrow">${tx('confession')}</p><h1>${tx('cTitle')}</h1><p class="c-intro">${tx('cIntro')}</p><div class="c-doors"><button class="c-door" data-confession="share"><span class="c-door-mark" aria-hidden="true">✧</span><strong>${tx('cShare')}</strong><span>${tx('cShareSub')}</span><b aria-hidden="true">↗</b></button><button class="c-door c-door-listen" data-confession="list"><span class="c-door-mark" aria-hidden="true">⌑</span><strong>${tx('cOffer')}</strong><span>${tx('cOfferSub')}</span><b aria-hidden="true">↗</b></button></div><p class="c-disclaimer">${tx('cDisclaimer')}</p>${btn('cMine','mine','c-quiet')}${s.moderator?btn('cReview','review','c-quiet'):''}</div>`;
 if(s.view==='share')html=`<h1>${tx('cShare')}</h1><div class="c-paper">${audience()}<label class="c-label" for="c-theme">${tx('cTheme')}</label><select id="c-theme">${CONFESSION_THEMES.map(k=>`<option value="${k}" ${s.theme===k?'selected':''}>${tx('c_'+k)}</option>`).join('')}</select><label class="c-label" for="c-response">${tx('cResponse')}</label><select id="c-response">${CONFESSION_RESPONSES.map(k=>`<option value="${k}" ${s.responseType===k?'selected':''}>${tx('c_'+k)}</option>`).join('')}</select><label class="c-label" for="c-body">${tx('cBody')}</label><textarea id="c-body" maxlength="3000" placeholder="${tx('cPlaceholder')}">${esc(s.body)}</textarea><details class="c-audio" ${s.audio||s.recording?'open':''}><summary>${tx('cAudio')}</summary><p>${tx('cAudioNotice')}</p>${s.audio?`<audio controls preload="metadata" src="${s.audioURL}" aria-label="${tx('cPreview')}"></audio>${btn('cTextInstead','text-instead','c-secondary')}`:`${btn(s.recording?'stop':'record',s.recording?'stop':'record','c-secondary')}<label class="c-upload">${tx('upload')}<input id="c-upload" type="file" accept="audio/*" ${s.recording?'disabled':''}></label>`}</details>${s.textInstead?`<p class="c-status">${tx('cTextHelp')}</p>`:''}<label class="c-consent"><input id="c-consent" type="checkbox" ${s.consent?'checked':''}>${tx('cConsent')}</label>${btn('cSubmit','submit','',s.recording?'disabled':'')}</div>`;
 if(s.view==='success')html=`<div class="c-entrance">${lattice}<h1>${tx(s.success==='reply'?'cReplySent':'cSuccess')}</h1>${s.success==='reply'?'':`<p class="c-intro">${tx('cAfter')}</p>`}<p class="c-status">${tx(s.success==='reply'?'cReplyPending':'cPending')}</p>${s.support?`<p class="c-safety">${tx('cSupport')}</p>`:''}${btn('cMine','mine')}</div>`;
 if(s.view==='list')html=`<h1>${tx('cChoose')}</h1><p class="c-intro">${tx('cChooseSub')}</p>${s.reserved.map(x=>`<div class="c-paper">${meta(x)}<p>${tx('cReserved')} ${esc(new Date(x.reservedUntil).toLocaleString(prefs().language))}</p>${btn('cResume','read','',`data-id="${x.id}"`)}</div>`).join('')}<div class="c-list">${s.items.length?s.items.map(listRow).join(''):`<p class="c-empty">${tx('cEmpty')}</p>`}</div>${btn('cRefresh','list','c-quiet')}`;
 if(s.view==='mine')html=`<h1>${tx('cMine')}</h1><div class="c-list">${s.items.length?s.items.map(x=>`<button class="c-list-row" data-confession="read" data-id="${esc(x.id)}">${meta(x)}<span>${tx(x.kind==='reply'?'cOffer':'cShare')}</span>${status(x)}${x.thanked?`<span>${tx('cReceivedThanks')}</span>`:''}</button>`).join(''):`<p class="c-empty">${tx('cNoMine')}</p>`}</div>${btn('cRefresh','mine','c-quiet')}`;
 if(s.view==='detail'&&s.detail){const x=s.detail;html=`${item(x)}${x.mine&&x.kind==='confession'?`<div class="c-actions">${!x.closed?btn('cClose','close','c-quiet'):''}${btn('cDelete','delete','c-quiet')}</div>${s.reply?`${item(s.reply)}${s.reply.status==='approved'?`${btn(s.reply.thanked?'cThanked':'cThank','thank','c-secondary',s.reply.thanked?'disabled':'')}${btn('cReport','report-reply','c-quiet')}${btn('cBlock','block-reply','c-quiet')}`:''}`:''}`:!x.mine&&x.kind==='confession'?`<p class="c-status">${tx('cReserved')} ${esc(new Date(x.reservedUntil).toLocaleString(prefs().language))}</p><p class="c-status">${tx('cReservedNote')}</p><div class="c-paper"><h2>${tx('cListen')}</h2><p>${tx('cListenSub')}</p><label class="c-label" for="c-reply">${tx('cReplyLabel')}</label><textarea id="c-reply" maxlength="3000">${esc(s.replyDraft)}</textarea>${btn('cOffer','reply')}</div>${btn('cReport','report','c-quiet')}${btn('cBlock','block','c-quiet')}`:''}`;}
 if(s.view==='review')html=`<h1>${tx('cReview')}</h1><p class="c-intro">${tx('cReviewIntro')}</p><p class="c-safety">${tx('cSupport')}</p>${s.items.map(x=>`${item(x)}<div class="c-review-controls"><label class="c-label" for="note-${x.id}">${tx('cNote')}</label><input id="note-${x.id}" data-review-note="${x.id}" maxlength="500"><div class="c-actions">${btn('cApprove','approve','',`data-id="${x.id}"`)}${btn('cReject','reject','c-secondary',`data-id="${x.id}"`)}</div></div>`).join('')||`<p class="c-empty">${tx('cNoMine')}</p>`}${btn('cRefresh','review','c-quiet')}`;
 if(s.report)html+=`<div class="c-paper" role="group" aria-label="${tx('cReportTitle')}"><h2>${tx('cReportTitle')}</h2>${['unkind','pressure','danger','privacy','other'].map(k=>btn('c_'+k,'send-report','c-secondary',`data-reason="${k}"`)).join('')}${btn('cancel','cancel-report','c-quiet')}</div>`;
 return `<section class="confession-space">${s.view!=='room'?btn('cBack','room','c-back'):''}${s.busy?`<p role="status">${tx('cLoading')}</p>`:''}${s.error?`<p class="c-error" role="alert">${esc(s.error)}</p>`:''}${html}</section>`;
 }
 async function load(v){s.view=v;s.report=null;const r=await api(v==='list'?'list':v==='review'?'queue':'mine',{language:prefs().language});s.items=r.items;s.reports=r.reports||[];s.reserved=r.reserved||[];}
 async function read(id,claim=false){if(s.detail?.id!==id)s.replyDraft='';const r=await api(claim?'open':'read',{id});s.detail=r.item;s.reply=r.reply;s.view='detail';s.report=null;}
 function setAudio(file){if(s.audioURL)URL.revokeObjectURL(s.audioURL);s.audio=file;s.audioURL=file?URL.createObjectURL(file):null;s.textInstead=false;}
 async function click(el){const a=el.dataset.confession;if(!a)return false;if(s.busy)return true;
 if(s.recording&&!['stop'].includes(a))return true;
 if(a==='room'||a==='share'){s.view=a;s.error='';s.report=null;render();focusMain();return true;}
 if(a==='record'){try{stream=await navigator.mediaDevices.getUserMedia({audio:true});recorder=new MediaRecorder(stream);const chunks=[];recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=()=>{clearTimeout(timer);stream.getTracks().forEach(t=>t.stop());s.recording=false;const blob=new Blob(chunks,{type:recorder.mimeType});if(blob.size>5*1024*1024)s.error=t('cAudioLimit');else setAudio(blob);render();};recorder.start();s.recording=true;timer=setTimeout(()=>recorder.stop(),90000);render();}catch{stream?.getTracks().forEach(t=>t.stop());s.error=t('micError');render();}return true;}
 if(a==='stop'){recorder?.stop();return true;}
 if(a==='text-instead'){setAudio(null);s.textInstead=true;render();document.querySelector('#c-body')?.focus();return true;}
 if(a.startsWith('report')){s.report=a==='report-reply'?s.reply.id:s.detail.id;render();document.querySelector('.c-paper[role="group"]')?.scrollIntoView({behavior:'smooth'});return true;}
 if(a==='cancel-report'){s.report=null;render();return true;}
 await run(async()=>{
 if(['list','mine','review'].includes(a))await load(a);
 if(a==='open'||a==='read')await read(el.dataset.id,a==='open');
 if(a==='submit'){if((!s.body.trim()&&!s.audio)||!s.consent){s.error=t('cNeed');return;}const r=await api('share',{body:s.body,theme:s.theme,responseType:s.responseType,language:prefs().language,consent:s.consent});s.body='';s.consent=false;setAudio(null);s.success='share';s.support=r.supportSuggested;s.view='success';}
 if(a==='reply'){if(s.replyDraft.trim().length<3){s.error=t('cNeed');return;}const r=await api('reply',{id:s.detail.id,body:s.replyDraft,theme:s.detail.theme,responseType:s.detail.responseType,language:s.detail.language,consent:true});s.replyDraft='';s.support=r.supportSuggested;s.success='reply';s.view='success';}
 if(a==='thank'){await api('thank',{id:s.reply.id});await read(s.detail.id);}
 if(a==='close'){await api('close',{id:s.detail.id});await read(s.detail.id);}
 if(a==='delete'&&window.confirm(t('cDeleteConfirm'))){await api('delete',{id:s.detail.id});await load('mine');}
 if(a==='send-report'){await api('report',{id:s.report,reason:el.dataset.reason});s.report=null;s.error=t('cReported');await load('mine');}
 if(a==='block'||a==='block-reply'){await api('block',{id:a==='block-reply'?s.reply.id:s.detail.id});s.error=t('cBlocked');await load('mine');}
 if(a==='approve'||a==='reject'){await api('moderate',{id:el.dataset.id,decision:a==='approve'?'approved':'rejected',note:s.notes?.[el.dataset.id]||''});await load('review');}
 });return true;
 }
 function input(el){const keys={'c-body':'body','c-theme':'theme','c-response':'responseType','c-reply':'replyDraft'};if(keys[el.id])s[keys[el.id]]=el.value;if(el.id==='c-consent')s.consent=el.checked;if(el.dataset.reviewNote){s.notes??={};s.notes[el.dataset.reviewNote]=el.value;}}
 function change(el){input(el);if(el.id==='c-upload'){const f=el.files?.[0];if(f&&f.size<=5*1024*1024&&f.type.startsWith('audio/'))setAudio(f);else s.error=t('cAudioLimit');render();}}
 async function ready(){try{s.moderator=(await api('status')).moderator;render();}catch{/* Entrance remains usable; sharing errors are explicit. */}}
 window.addEventListener('pagehide',()=>{clearTimeout(timer);stream?.getTracks().forEach(t=>t.stop());});
 return {view,click,input,change,ready,isRecording:()=>s.recording,hasDraft:()=>!!s.body.trim()||!!s.replyDraft.trim()||!!s.audio};
}
